def find_adverb_position(sentence, return_adverb_twice=False):
    # List of common adverbs
    adverbs = [
        "clearly", "seriously", "unfortunately", "obviously", "generally", "specifically",
        "actually", "basically", "possibly", "unfortunately", "fortunately"
    ]

